package com.tdc.nhom6.doanjava1.controller;
import com.tdc.nhom6.doanjava1.model.*;import com.tdc.nhom6.doanjava1.service.DocumentService;import javax.servlet.http.*;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.servlet.mvc.support.RedirectAttributes;import java.io.IOException;import java.net.URLEncoder;import java.nio.charset.StandardCharsets;
@Controller @RequestMapping("/documents") public class DocumentController {
 private final DocumentService docs;public DocumentController(DocumentService d){docs=d;}
 @GetMapping public String list(HttpSession s,Model m){m.addAttribute("account",s.getAttribute("currentUser"));m.addAttribute("documents",docs.findAll());return "documents/list";}
 @GetMapping("/upload") public String uploadForm(HttpSession s,Model m){Account a=(Account)s.getAttribute("currentUser");if(a==null)return "redirect:/login";m.addAttribute("account",a);return "documents/upload";}
 @PostMapping("/upload") public String upload(@RequestParam("file")MultipartFile file,@RequestParam String title,@RequestParam(required=false)String author,@RequestParam(required=false)String description,@RequestParam(required=false)String documentType,HttpSession s,RedirectAttributes ra){Account a=(Account)s.getAttribute("currentUser");if(a==null)return "redirect:/login";try{docs.upload(file,title,author,description,documentType,a.getId());ra.addFlashAttribute("success","Đã upload tài liệu '"+title+"'!");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/documents";}
 @GetMapping("/download/{id}") public void download(@PathVariable Long id,HttpServletResponse res)throws IOException{DigitalDocument d=docs.findById(id);if(d==null){res.setStatus(404);return;}docs.incrementDownload(id);String type=d.getContentType()==null?"application/octet-stream":d.getContentType();res.setContentType(type);String encoded=URLEncoder.encode(d.getFileName(),StandardCharsets.UTF_8).replace("+","%20");res.setHeader("Content-Disposition",(type.contains("pdf")?"inline":"attachment")+"; filename*=UTF-8''"+encoded);res.getOutputStream().write(d.getFileData());}
 @PostMapping("/delete/{id}") public String delete(@PathVariable Long id,HttpSession s,RedirectAttributes ra){Account a=(Account)s.getAttribute("currentUser");if(a==null||!a.canManage())return "redirect:/documents";docs.delete(id);ra.addFlashAttribute("success","Đã xóa tài liệu!");return "redirect:/documents";}
}